"""Small, privacy-conscious client for OpenAI's Responses API.

Only Python's standard library is used.  Prompts are sent in an HTTPS request
body, responses are not stored by OpenAI by default, and prompt text is never
included in this module's exceptions or logs.
"""

from __future__ import annotations

import json
import os
import socket
import urllib.error
import urllib.request
from typing import Any, Mapping


RESPONSES_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-4.1-mini"


class OpenAIError(RuntimeError):
    """An error returned by, or encountered while contacting, OpenAI."""

    def __init__(self, message: str, *, status: int | None = None) -> None:
        super().__init__(message)
        self.status = status


def _api_error_message(body: bytes, status: int) -> str:
    """Describe a service error without echoing any server-returned input."""
    # Deliberately do not surface the response body: validation errors can quote
    # request values, including private prompt text.
    del body
    return f"OpenAI API request failed with HTTP status {status}"


def _output_text(response: Mapping[str, Any]) -> str:
    # Some Responses API representations include this convenience field.
    direct = response.get("output_text")
    if isinstance(direct, str):
        return direct

    parts: list[str] = []
    output = response.get("output", [])
    if isinstance(output, list):
        for item in output:
            if not isinstance(item, Mapping) or item.get("type") != "message":
                continue
            content = item.get("content", [])
            if not isinstance(content, list):
                continue
            for part in content:
                if not isinstance(part, Mapping):
                    continue
                if part.get("type") == "output_text" and isinstance(part.get("text"), str):
                    parts.append(part["text"])
    if parts:
        return "".join(parts)
    raise OpenAIError("The OpenAI response did not contain text output")


class OpenAIClient:
    """Synchronous client for text prompts sent to the Responses API."""

    def __init__(
        self,
        api_key: str | None = None,
        *,
        model: str = DEFAULT_MODEL,
        timeout: float = 60.0,
        url: str = RESPONSES_URL,
    ) -> None:
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY", "")
        if not self.api_key:
            raise ValueError("Set OPENAI_API_KEY or pass api_key")
        if not model:
            raise ValueError("model must not be empty")
        if timeout <= 0:
            raise ValueError("timeout must be positive")
        if not url.startswith("https://"):
            raise ValueError("url must use HTTPS")
        self.model = model
        self.timeout = timeout
        self.url = url

    def create(self, prompt: str, **parameters: Any) -> dict[str, Any]:
        """Send *prompt* and return the complete decoded Responses API object.

        Extra keyword arguments become Responses API request parameters.  The
        privacy-preserving ``store=False`` default may be explicitly overridden.
        """
        if not isinstance(prompt, str):
            raise TypeError("prompt must be a string")

        payload: dict[str, Any] = {
            "model": self.model,
            "input": prompt,
            "store": False,
        }
        payload.update(parameters)
        data = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        request = urllib.request.Request(
            self.url,
            data=data,
            headers={
                "Authorization": f"Bearer {self.api_key}",
                "Content-Type": "application/json",
                "Accept": "application/json",
            },
            method="POST",
        )

        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                body = response.read()
        except urllib.error.HTTPError as exc:
            # Read the service response, but never include the submitted body.
            body = exc.read()
            raise OpenAIError(
                _api_error_message(body, exc.code), status=exc.code
            ) from None
        except (urllib.error.URLError, TimeoutError, socket.timeout) as exc:
            reason = getattr(exc, "reason", exc)
            raise OpenAIError(f"Could not reach OpenAI: {reason}") from None

        try:
            decoded = json.loads(body.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            raise OpenAIError("OpenAI returned an invalid JSON response") from None
        if not isinstance(decoded, dict):
            raise OpenAIError("OpenAI returned an unexpected JSON response")
        return decoded

    def respond(self, prompt: str, **parameters: Any) -> str:
        """Send a text prompt and return the response's combined text output."""
        return _output_text(self.create(prompt, **parameters))


def send_prompt(
    prompt: str,
    *,
    api_key: str | None = None,
    model: str = DEFAULT_MODEL,
    timeout: float = 60.0,
    **parameters: Any,
) -> str:
    """Convenience function that sends one prompt and returns its text output."""
    return OpenAIClient(api_key, model=model, timeout=timeout).respond(
        prompt, **parameters
    )


__all__ = [
    "DEFAULT_MODEL",
    "OpenAIClient",
    "OpenAIError",
    "RESPONSES_URL",
    "send_prompt",
]

