/bin/bash -lc "python3 -m py_compile openai_client.py && python3 - <<'PY'
import json
from unittest.mock import patch
import openai_client

class Reply:
    def __enter__(self): return self
    def __exit__(self, *args): pass
    def read(self):
        return json.dumps({'output': [{'type': 'message', 'content': [{'type': 'output_text', 'text': 'ok'}]}]}).encode()

def fake_open(request, timeout):
    payload = json.loads(request.data)
    assert payload == {'max_output_tokens': 10, 'model': 'gpt-4.1-mini', 'input': 'private', 'store': False}
    return Reply()

client = openai_client.OpenAIClient('test-key')
with patch('urllib.request.urlopen', fake_open):
    assert client.respond('private', max_output_tokens=10) == 'ok'
try:
    client.create('private', store=True)
except ValueError:
    pass
else:
    raise AssertionError('store override was accepted')
print('compile and mocked request checks passed')
PY"

